    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: A JSON‑serialisable representation of the point
    """
    # Allow passing None
    if value is None:
        return None

    # Try the standard geo‑interface used by many libraries (e.g. Shapely, GeoJSON)
    geo = getattr(value, "__geo_interface__", None)
    if geo is not None:
        # If it's a callable (some libraries expose it as a property),
        # call it to get the mapping.
        if callable(geo):
            try:
                geo = geo()
            except Exception:
                pass
        if isinstance(geo, dict):
            return geo

