def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess, os, concurrent.futures
    # Helper to build command string length
    def _cmd_len(parts: Sequence[str]) -> int:
        # approximate length: sum of lengths + spaces
        return sum(len(p) for p in parts) + max(0, len(parts) - 1)

    # Partition varargs into batches that respect _max_length
    batches: list[list[str]] = []
    current: list[str] = []
    current_len = _cmd_len(cmd)
    for arg in varargs:
        # length if added
        added_len = len(arg) + 1  # space
        if current_len + added_len > _max_length and current:
            batches.append(current)
            current = []
            current_len = _cmd_len(cmd)
        current.append(arg)
        current_len += added_len
    if current:
        batches.append(current)

    # Function to run a single batch
    def _run_batch(batch: list[str]) -> tuple[int, bytes]:
        full_cmd = list(cmd) + batch
        try:
            if color and hasattr(os, "isatty") and os.isatty(0):
                # Attempt to run in a pseudo-terminal
                import pty, tty
                master_fd, slave_fd = pty.openpty()
                proc = subprocess.Popen(
                    full_cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    stdin=os.fdopen(slave_fd, "wb"),
                    **kwargs
                )
                stdout = b""
                while True:
                    data = os.read(master_fd, 4096)
                    if not data:
                        break
                    stdout += data
                proc.wait()
                return (proc.returncode, stdout)
            else:
                result = subprocess.run(full_cmd, stdout=subprocess.PIPE, **kwargs, encoding=None)
                return (result.returncode, result.stdout)
        except Exception as e:
            return (-1, str(e).encode())

    # Run batches concurrently if needed
    if target_concurrency > 1:
        exit_codes = []
        out_buf = b""
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = [executor.submit(_run_batch, batch) for batch in batches]
            for fut in concurrent.futures.as_completed(futures):
                ret, out = fut.result()
                exit_codes.append(ret)
                out_buf += out
        # If any non-zero exit code, propagate the first one
        exit_code = exit_codes[0] if exit_codes else 0
        return (exit_code, out_buf)
    else:
        # Sequential execution
        ret, out = _run_batch(batches[0]) if batches else (0, b"")
        for batch in batches[1:]:
            r, o = _run_batch(batch)
            if ret == 0:
                ret = r
            out += o
        return (ret, out)

