def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison
    Parse a dotted version string into a tuple of integers.
    Non‑numeric components are ignored. Empty input yields an empty tuple."""
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for part in parts:
        # keep digits only at the beginning
        i = 0
        while i < len(part) and part[i].isdigit():
            i += 1
        if i > 0:
            try:
                nums.append(int(part[:i]))
            except ValueError:
                pass
    return tuple(nums)

