def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os, sys

    if not sys.platform.startswith("win"):
        return cmd

    if not cmd:
        return cmd

    # Attempt to resolve the first argument to an absolute path
    first = cmd[0]
    if not os.path.isabs(first):
        try:
            abs_first = os.path.abspath(first)
            if os.path.isfile(abs_first):
                first = abs_first
        except Exception:
            pass

    # If the first argument is a Python script, prepend the interpreter
    if os.path.isfile(first) and first.lower().endswith(".py"):
        new_cmd = (sys.executable, first) + cmd[1:]
    else:
        new_cmd = cmd

    # Windows commandline quoting (issue 8557 handling)
    def win_quote(arg: str) -> str:
        if not arg or any(ch in arg for ch in " \t"):
            out = ['"']
            backslash = 0
            for ch in arg:
                if ch == "\\":
                    backslash += 1
                elif ch == "\"":
                    out.append("\\" * (backslash * 2 + 1))
                    out.append("\"")
                    backslash = 0
                else:
                    out.append("\\" * (backslash * 2))
                    out.append(ch)
                    backslash = 0
            out.append("\\" * (backslash * 2))
            out.append("\"")
            return "".join(out)
        return arg

    return tuple(win_quote(a) for a in new_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd

    import os, shutil

    first = cmd[0]
    args = list(cmd[1:])

    if os.name == "nt":
        # If the first argument is a file, try to interpret a shebang line
        if os.path.isfile(first):
            try:
                with open(first, "rb") as fh:
                    line = fh.readline()
            except Exception:
                line = b""
            if line.startswith(b"#!"):
                shebang = line[2:].strip().decode(errors="ignore")
                parts = shebang.split()
                if parts:
                    interpreter = parts[0]
                    # Resolve interpreter with PATH
                    interp_path = shutil.which(interpreter)
                    if interp_path:
                        return (interp_path, *args)  # prepend interpreter, skip original script

        # If the file looks like a python script, prepend python interpreter
        _, ext = os.path.splitext(first)
        if ext.lower() in (".py", ".pyw"):
            python_exe = shutil.which("python")
            if python_exe:
                return (python_exe, first, *args)

    return cmd

