def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorating_function(user_function):
        cache = {}
        hits = 0
        misses = 0

        def _make_key(args, kwds, typed):
            # key based on args and sorted kwargs
            kwkey = tuple(sorted(kwds.items())) if kwds else ()
            if typed:
                # include types of arguments in key to avoid accidental matches
                return (args, kwkey,
                        tuple(type(v) for v in args),
                        tuple(type(v) for _, v in kwkey))
            return (args, kwkey)

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = 0
            misses = 0

        def cache_info():
            return {'hits': hits, 'misses': misses,
                    'maxsize': maxsize, 'currsize': len(cache)}

        def wrapper(*args, **kwds):
            nonlocal hits, misses
            key = _make_key(args, kwds, typed)
            now = timer()
            if key in cache:
                value, stamp = cache[key]
                if now - stamp < ttl:
                    # refresh ordering
                    cache.pop(key)
                    cache[key] = (value, stamp)
                    hits += 1
                    return value
                else:
                    # expired entry
                    cache.pop(key)
                    misses += 1
            else:
                misses += 1
            result = user_function(*args, **kwds)
            cache[key] = (result, now)
            if maxsize and len(cache) > maxsize:
                # pop the oldest item (first key)
                cache.popitem(last=False)
            return result

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        wrapper.__wrapped__ = user_function
        return wrapper

    return decorating_function

