@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        exc_type = type(e).__name__
        exc_msg = str(e)
        output = [f"{exc_type}: {exc_msg}"]
        tb = getattr(e, "__traceback__", None)
        if tb is not None:
            output.append("Traceback (most recent call last):")
            frame = tb
            depth = 0
            while frame is not None and depth < max_level:
                f = frame.tb_frame
                lineno = frame.tb_lineno
                func_name = f.f_code.co_name
                filename = f.f_code.co_filename or ""
                if filename:
                    parts = filename.split('/')
                    if len(parts) > max_path_level:
                        filename = '/'.join(parts[-max_path_level:])
                output.append(f'  File "{filename}", line {lineno}, in {func_name}')
                frame = frame.tb_next
                depth += 1
            if frame is not None and depth >= max_level:
                output.append("    ...")
        return "\n".join(output)

