def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string, trimming the stack depth
    and file path depth according to `max_level` and `max_path_level`.
    """
    try:
        import traceback
        import os
    except Exception:
        # Fallback: just return the string representation
        return str(e)

    # Helper to shorten file paths
    def shorten_path(path, max_parts):
        parts = path.split(os.sep)
        if len(parts) <= max_parts:
            return path
        return os.sep.join(parts[-max_parts:])

    # Extract and format the traceback frames
    tb_lines = traceback.format_exception(e.__class__, e, e.__traceback__, chain=True)
    # Trim to maximum number of lines (frames + exception message)
    tb_lines = tb_lines[:max_level]

    # Replace file paths with shortened versions
    out_lines = []
    for line in tb_lines:
        # Look for lines that start with '  File "path", line '
        stripped = line.lstrip()
        if stripped.startswith('File'):
            # Find the quoted file path
            first_quote = line.find('"')
            if first_quote != -1:
                second_quote = line.find('"', first_quote + 1)
                if second_quote != -1:
                    original_path = line[first_quote + 1:second_quote]
                    short_path = shorten_path(original_path, max_path_level)
                    line = line.replace(original_path, short_path, 1)
        out_lines.append(line)

    return ''.join(out_lines)

