@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception to a readable string with a limited call stack depth and
    truncated file path depth.
    """
    import traceback
    import os

    parts = []

    def _format(exc):
        tb = exc.__traceback__
        if tb is None:
            return
        extracted = traceback.extract_tb(tb, limit=max_level)
        for frame in extracted:
            # Truncate file path
            path = frame.filename
            segs = path.split(os.sep)
            if len(segs) > max_path_level:
                path = os.sep.join(segs[-max_path_level:])
            parts.append(f'File "{path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                parts.append(f'    {frame.line.strip()}')
        parts.append(f'{type(exc).__name__}: {exc}')

    _format(e)

    # Handle exception chaining
    if e.__cause__:
        parts.append("\nThe above exception was the direct cause of the following exception:")
        _format(e.__cause__)
    elif e.__context__ and not e.__suppress_context__:
        parts.append("\nDuring handling of the above exception, another exception occurred:")
        _format(e.__context__)

    return "\n".join(parts)

