@classmethod
    def _reset_logging(cls):
        """
        Reset the root logger configuration to the default state.
        This removes all handlers, closes them, and restores the
        root logger's level to WARNING.
        """
        # Attempt to access the logging module; if it is not available,
        # silently ignore.
        try:
            root = logging.getLogger()
            # Remove and close all handlers attached to the root logger.
            for handler in root.handlers[:]:
                try:
                    handler.close()
                except Exception:
                    pass
                root.removeHandler(handler)
            # Restore the default root level.
            root.setLevel(logging.WARNING)
        except Exception:
            # If logging is not configured or unavailable, ignore silently.
            pass

def _getTargetClass(self):
    """Define this to return the implementation in use, without the 'Py' or 'Fallback' suffix."""
    cls_name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if cls_name.endswith(suffix):
            base_name = cls_name[:-len(suffix)]
            module = __import__(self.__class__.__module__, fromlist=[base_name])
            return getattr(module, base_name)
    return self.__class__

