def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build graph: adjacency list and indegree count
    adj = {}
    indegree = {}
    # Keep track of first appearance index for deterministic ordering
    first_index = {}
    idx = 0
    for order in orderings:
        for elem in order:
            if elem not in indegree:
                indegree[elem] = 0
                adj[elem] = []
                if elem not in first_index:
                    first_index[elem] = idx
                    idx += 1
            # add edges between consecutive elements
        for u, v in zip(order, order[1:]):
            if v not in adj[u]:  # avoid duplicate edges
                adj[u].append(v)
                indegree[v] += 1
    # Kahn's algorithm with deterministic ordering
    import heapq
    heap = []
    for node in indegree:
        if indegree[node] == 0:
            heapq.heappush(heap, (first_index[node], node))
    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for nb in adj[node]:
            indegree[nb] -= 1
            if indegree[nb] == 0:
                heapq.heappush(heap, (first_index[nb], nb))
    if len(result) != len(indegree):
        raise ValueError("Orderings contain a cycle or conflict.")
    return result

