def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # If the object itself declares interfaces, use them
    provides = getattr(object, "__provides__", None)
    if provides is not None:
        return provides

    # If the object is an instance, fall back to its class
    if not isinstance(object, type):
        cls = type(object)
        provides = getattr(cls, "__provides__", None)
        if provides is not None:
            return provides

    # If we reached here, the class itself is the object
    # and it does not declare any interfaces – return an empty declaration
    try:
        # Use the IProvide interface as an empty declaration
        from zope.interface.interfaces import IProvide
        return IProvide()
    except Exception:
        # Fallback to an empty tuple if IProvide is not available
        return tuple()

