def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.

    The result contains only the most derived classes among the input list:
    a class is omitted if any other class in the list is a subclass of it.
    The relative order of the remaining classes is preserved.
    Duplicate classes are removed, keeping the first occurrence.
    """
    minimal = []
    for cls in classes:
        # Skip if cls is a superclass of any other class in the list
        redundant = False
        for other in classes:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    redundant = True
                    break
            except TypeError:
                # ignore non-class objects
                pass
        if redundant:
            continue
        if cls not in minimal:
            minimal.append(cls)
    return minimal

