def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Attempt to get a class level mapping of attribute names to descriptions.
    # The mapping is expected to be a dictionary named ATTR_DESCRIPTIONS
    # defined on the concrete subclass that implements the interface.
    #
    # If `all` is True, return the entire mapping.
    # If `all` is False, only return entries for which the instance actually
    # defines a corresponding attribute (via hasattr). This allows the
    # interface to expose descriptions for a subset of attributes that have
    # been configured or initialized.
    descriptions = getattr(self.__class__, "ATTR_DESCRIPTIONS", {})
    if not isinstance(descriptions, dict):
        return {}

    if all:
        return dict(descriptions)

    result = {}
    for name, desc in descriptions.items():
        if hasattr(self, name):
            result[name] = desc
    return result

