def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))

    # Determine how to iterate over points
    points_obj = getattr(self, "points", None)
    if points_obj is None:
        raise AttributeError("Object has no 'points' attribute")

    # If points is a mapping, iterate over items (coord, value)
    if isinstance(points_obj, dict):
        iterable = points_obj.items()
    else:
        iterable = points_obj

    for item in iterable:
        # Try to interpret item as (coord, value)
        try:
            coord, value = item
        except Exception:
            # If single value, treat as value with no coord
            coord, value = (), item

        # Convert coordinate to string
        if isinstance(coord, (list, tuple, set, frozenset)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord) if coord is not None else ""

        # Convert value to string
        if isinstance(value, (list, tuple, set, frozenset)):
            value_str = separator.join(map(str, value))
        else:
            value_str = str(value)

        # Build line: coordinate part first, then value part
        if coord_str:
            line = separator.join([coord_str, value_str])
        else:
            line = value_str
        lines.append(line)

    return "\n".join(lines)

