    if points_iter is None:
        if _is_iterable(self):
            points_iter = self
        else:
            points_iter = []  # nothing to iterate over

    for point in points_iter:
        # Handle dictionary or tuple cases
        if isinstance(point, tuple) and len(point) == 2:
            coord, val = point
        else:
