    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences
    try:
        from typing import Iterable
    except Exception:
        Iterable = (list, tuple, set, frozenset, dict)

    # If sequence is directly a Source, it's not acceptable
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source class not defined; skip check
        pass

    # If seq is a FillRequest itself, it's acceptable
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest class not defined; fallback to type check below
        pass

    # If seq is iterable, check presence of any FillRequest element
    if isinstance(seq, (list, tuple, set, frozenset, dict)):
        return any(isinstance(item, FillRequest) for item in seq)
    # For any other iterable
    try:
        iter(seq)
    except TypeError:
        return False
    else:
        return any(isinstance(item, FillRequest) for item in seq)

