def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the coordinate has the right dimensionality
    if not isinstance(coord, (list, tuple)):
        return
    if hasattr(self, "edges") and len(coord) != len(self.edges):
        return

    indices = []
    for dim, x in enumerate(coord):
        edges = self.edges[dim]
        # Coordinate must be within the histogram bounds
        if x < edges[0] or x >= edges[-1]:
            return
        # Find bin index by linear search
        for i in range(len(edges) - 1):
            if edges[i] <= x < edges[i + 1]:
                indices.append(i)
                break

    # Convert to a tuple for indexing
    idx = tuple(indices)

    # Update the bin contents, handling both array and dict cases
    try:
        self.contents[idx] += weight
    except (KeyError, TypeError):
        # If contents is a dict that hasn't been initialized for this bin
        self.contents[idx] = weight if isinstance(self.contents, dict) else weight

    # Optional: keep track of the total weight, if such an attribute exists
    if hasattr(self, "total_weight"):
        self.total_weight += weight

