def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coord is a sequence
    if isinstance(coord, (int, float)):
        coord = [coord]
    try:
        coord = list(coord)
    except TypeError:
        raise TypeError("coord must be a number or an iterable of numbers")

    # Check dimensionality
    if len(coord) != len(self.edges):
        raise ValueError(f"coord has {len(coord)} dimensions but histogram expects {len(self.edges)}")

    # Find bin indices for each dimension
    indices = []
    for c, edges in zip(coord, self.edges):
        # Outside histogram bounds => ignore
        if c < edges[0] or c >= edges[-1]:
            return
        # Locate bin index
        # Using shell method as fallback if numpy not available
        # But prefer numpy.searchsorted for performance
        try:
            import numpy as _np
            idx = _np.searchsorted(edges, c, side='right') - 1
        except ImportError:
            # Simple linear search
            idx = -1
            for j in range(len(edges) - 1):
                if edges[j] <= c < edges[j + 1]:
                    idx = j
                    break
        if idx < 0:
            return
        indices.append(idx)

    # Increment the histogram bin
    # Support scalar (1D) or multi-dimensional arrays
    if isinstance(self.data, (list, tuple)):
        # For simple list-based implementation
        # Build nested indices
        ref = self.data
        for i, idx in enumerate(indices[:-1]):
            ref = ref[idx]
        ref[indices[-1]] += weight
    else:
        # Assume numpy.ndarray or similar
        self.data[tuple(indices)] += weight

