def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    def _is_valid_label_key(key_str):
        """Simple validation that matches characters allowed in label keys."""
        allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.")
        # Require key to be non-empty, start and end with an alphanumeric character,
        # and all characters must be from the allowed set.
        if not key_str:
            return False
        if not key_str[0].isalnum() or not key_str[-1].isalnum():
            return False
        return all(ch in allowed for ch in key_str)

    def _is_valid_label_value(value_str):
        """Simple validation that matches characters allowed in label values."""
        allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-.")
        # Require value to be non-empty, start and end with an alphanumeric character,
        # and all characters must be from the allowed set.
        if not value_str:
            return False
        if not value_str[0].isalnum() or not value_str[-1].isalnum():
            return False
        return all(ch in allowed for ch in value_str)

    errors = []

    for key, val in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not _is_valid_label_key(key_str):
                errors.append(
                    {key_str: f"Label key '{key_str}' does not match the regex [...]"}
                )

        # Validate value type
        if not isinstance(val, (str, bytes)):
            errors.append({repr(val): "expected string or bytes-like object"})
        else:
            val_str = val.decode() if isinstance(val, bytes) else val
            if not _is_valid_label_value(val_str):
                errors.append(
                    {val_str: f"Label value '{val_str}' does not match the regex [...]"}
                )

    if errors:
        raise ValidationError(errors)

