def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generate a default observer_schema portion from a Kubernetes resource manifest.

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.  If ``first_level`` is ``True``, the
    values of identifying fields (`apiVersion`, `kind`, and the relevant
    fields inside ``metadata``) are copied from the manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): Indicates that the dictionary represents the
            whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    def _process_value(val, preserve_identifying=False):
        """Recursively process a value, replacing primitives with None."""
        if isinstance(val, dict):
            return {k: _process_value(v, preserve_identifying=False) for k, v in val.items()}
        elif isinstance(val, list):
            return [_process_value(item, preserve_identifying=False) for item in val]
        else:
            # Primitive value: replace with None (unless it is an identifying field
            # handled at the top level, which is already dealt with by the caller).
            return None

    if not isinstance(manifest_dict, dict):
        return None

    result = {}
    for key, value in manifest_dict.items():
        if first_level and key in ('apiVersion', 'kind'):
            # Directly copy identifying top-level fields
            result[key] = value
        elif key == 'metadata':
            # Handle metadata separately
            if isinstance(value, dict):
                meta = {}
                for mkey, mval in value.items():
                    if first_level and mkey in ('name', 'namespace', 'uid'):
                        meta[mkey] = mval
                    else:
                        meta[mkey] = _process_value(mval, preserve_identifying=False)
                result[key] = meta
            else:
                result[key] = _process_value(value, preserve_identifying=False)
        else:
            # For all other keys simply process the value recursively
            result[key] = _process_value(value, preserve_identifying=False)

    return result

