def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update a partial ``last_applied_manifest`` dictionary from a
    partial Kubernetes response according to an *observer_schema*.

    The observer_schema is a nested structure which mirrors the shape of the
    Kubernetes object.  For each key in the schema the function ensures that
    the same key exists in ``response``; if it does, the value is copied into
    ``last_applied_manifest`` unless it is already present.
    Nested dictionaries and lists are processed recursively.

    Raises:
        KeyError: If ``response`` does not contain an observed field.
    """
    for key, subschema in observer_schema.items():
        # The key must be present in the response
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' missing from Kubernetes response"
            )

        resp_val = response[key]

        # If the subschema is a dict, treat this key as a nested dict
        if isinstance(subschema, dict):
            # Ensure a dict exists in the target; create if missing or replace non‑dict
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                last_applied_manifest[key] = {}
            # Recurse into the nested dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], subschema, resp_val
            )

        # If the subschema is a list, treat this key as a list of items
        elif isinstance(subschema, list):
            # Each item in the list is described by the first element of ``subschema``.
            # ``subschema`` may contain an empty list when the type is unknown.
            item_schema = subschema[0] if subschema else None

            # Ensure a list exists in the target; create if missing
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], list):
                last_applied_manifest[key] = []

            target_list = last_applied_manifest[key]
            # For each element in the response list, copy it into the target list.
            # If the element schema is a dict, recurse; otherwise copy the value.
            for element in resp_val:
                if isinstance(item_schema, dict):
                    if isinstance(element, dict):
                        target_list.append(element)
                    else:
                        # Unexpected type – just copy the raw value
                        target_list.append(element)
                else:
                    target_list.append(element)

        # Otherwise the field is a scalar; copy if not already present
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = resp_val
    return last_applied_manifest

