def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: The updated observer_schema mapping.
    """
    # Ensure the application spec has the expected attributes
    if not hasattr(app, "spec"):
        return {}

    # Retrieve the manifest of Kubernetes resources
    manifest = getattr(app.spec, "manifest", {})
    if not isinstance(manifest, dict):
        # Nothing to do if the manifest is not a dictionary
        return {}

    # Retrieve or initialise the custom observer schema mapping
    observer_schema = getattr(app.spec, "observer_schema", {})
    if not isinstance(observer_schema, dict):
        observer_schema = {}

    # For each resource in the manifest, add a default empty schema
    # if none has been explicitly defined for that resource name.
    for name, _resource in manifest.items():
        if name not in observer_schema:
            # A default observer schema is simply an empty mapping;
            # it can be expanded later if needed.
            observer_schema[name] = {}

    # Persist the updated mapping back on the application spec
    app.spec.observer_schema = observer_schema

    return observer_schema

