        errors = getattr(self, 'errors') or []
    elif hasattr(self, 'error_list'):
        errors = getattr(self, 'error_list') or []
    elif hasattr(self, 'error'):
        err = getattr(self, 'error')
        if isinstance(err, (list, tuple)):
            errors = err
        elif isinstance(err, str):
            errors = [err]
