    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Gather entries from inventory into a list of dicts
    items = []
    if isinstance(inventory, dict):
        # Inventory might be a mapping from logical_path to records or a more complex dict
        # Use values by default, but try to unwrap simple tuple mappings
        try:
            items = list(inventory.values())
        except Exception:
            items = []
    elif isinstance(inventory, (list, tuple)):
        items = list(inventory)
    else:
        try:
            items = list(inventory.items())
        except Exception:
            items = []

