    extracted = []
    for it in items:
        if isinstance(it, tuple) and len(it) == 2 and isinstance(it[1], dict):
            extracted.append(it[1])
        elif isinstance(it, dict):
            extracted.append(it)
    items = extracted

    result = {}
    # First pass: collect entries for the requested version
    for entry in items:
        if not isinstance(entry, dict):
            continue
        v = entry.get("version")
        if v != version:
            continue
        lp = entry.get("logical_path")
        cf = entry.get("content_file")
        if lp is None or cf is None:
