def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input
    if not isinstance(inventory, dict) or 'snapshots' not in inventory:
        return {}
    snapshots = inventory.get('snapshots', {})
    if version not in snapshots:
        return {}

    # Helper to recursively walk the tree
    def walk_tree(node_hash, prefix, result):
        node = inventory.get('tree', {}).get(node_hash)
        if node is None:
            return
        node_type = node.get('type')
        if node_type == 'directory':
            # for each entry, recurse
            entries = node.get('entries', {})
            for entry_name, child_hash in entries.items():
                child_path = f"{prefix}/{entry_name}" if prefix else entry_name
                walk_tree(child_hash, child_path, result)
        elif node_type == 'file':
            # file node. content hash is node's id (or hash)
            content_hash = node.get('id') or node_hash
            if prefix in result:
                result[prefix].add(content_hash)
            else:
                result[prefix] = {content_hash}
        else:
            # ignore other node types (symlink, etc.)
            return

    # Start from the snapshot's tree
    root_hash = snapshots[version].get('tree')
    if not root_hash:
        return {}

    logical_map = {}
    walk_tree(root_hash, '', logical_map)
    return logical_map

