def validate_fixity(self, fixity, manifest_files):
    """
    Validate a ``fixity`` block in an inventory.

    Parameters
    ----------
    fixity : dict
        Either a mapping ``{filename: checksum}`` or a structure
        ``{algorithm: {filename: checksum}}``.  The checksum must be a
        non‑empty hexadecimal string.
    manifest_files : iterable
        Collection of (str) file names that are known from the manifest.

    Returns
    -------
    bool
        ``True`` if the structure is valid, otherwise raises a
        ``ValueError`` describing the problem.
    """
    if not isinstance(fixity, dict):
        raise ValueError(f"fixity must be a mapping, got {type(fixity).__name__}")

    manifest_set = set(manifest_files)
    if not manifest_set:
        raise ValueError("manifest_files cannot be empty")

    def _check_entries(entries):
        """Validate a mapping of file → checksum."""
        if not isinstance(entries, dict):
            raise ValueError(f"Expected a mapping of file to checksum, got {type(entries).__name__}")
        for fn, ck in entries.items():
            if not isinstance(fn, str):
                raise ValueError(f"File names must be strings; got {type(fn).__name__}")
            if fn not in manifest_set:
                raise ValueError(f"Fixity references unknown file '{fn}'")
            if not isinstance(ck, str) or not ck:
                raise ValueError(f"Checksum for '{fn}' must be a non‑empty string")
            # Quick hex validation (characters a–f and 0–9)
            if not all(c in "0123456789abcdefABCDEF" for c in ck):
                raise ValueError(f"Checksum for '{fn}' contains non‑hex characters")

    # Detect whether the top level is {"filename": "ck"} or
    # {"algorithm": {"filename": "ck"}}.  The latter will have dict values
    # for each key.
    if all(isinstance(v, dict) for v in fixity.values()) and fixity:
        # Mapping algorithm → {file: ck}
        for algo, entries in fixity.items():
            if not isinstance(algo, str) or not algo:
                raise ValueError(f"Algorithm names must be non‑empty strings; got {repr(algo)}")
            _check_entries(entries)
    else:
        # Direct mapping file → checksum
        _check_entries(fixity)

    return True

