def _explore_folder(folder):
    """
    Get packages' data from folder
    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from XML base name to a list of file names that share that base name.
    """
    import os

    # Map base name (without extension) to list of file names within the folder.
    base_to_files = {}
    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue
            name, ext = os.path.splitext(entry)
            base_to_files.setdefault(name, []).append(entry)
    except (OSError, FileNotFoundError):
        # If the folder cannot be accessed, return empty dict
        return {}

    # Keep only groups that contain an XML file
    result = {}
    for base, files in base_to_files.items():
        if any(f.lower().endswith('.xml') for f in files):
            result[base] = sorted(files)

    return result

