def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        Nome do arquivo XML sem extensão.
    file_path : str
        Caminho completo do arquivo em análise.

    Returns
    -------
    dict
        Um dicionário contendo a chave do prefixo do arquivo e um sub-dicionário
        com o tipo (`asset`, `rendition` ou `unknown`) e o caminho completo.
    """
    try:
        # Determinar a extensão do arquivo
        idx = file_path.rfind('.')
        ext = file_path[idx:].lower() if idx != -1 else ''
        asset_exts = {'.psd', '.ai', '.svg', '.dxf', '.dwg', '.pdf', '.ps', '.eps'}
        rendition_exts = {
            '.jpg', '.jpeg', '.png', '.gif', '.webp', '.mp4',
            '.mov', '.avi', '.mpg', '.wmv', '.flv'}

        if ext in asset_exts:
            file_type = 'asset'
        elif ext in rendition_exts:
            file_type = 'rendition'
        else:
            # Se for XML, tentar identificar pelo conteúdo
            if ext == '.xml':
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                if ('<asset>' in content) or ('type="asset"' in content):
                    file_type = 'asset'
                elif ('<rendition>' in content) or ('type="rendition"' in content):
                    file_type = 'rendition'
                else:
                    file_type = 'unknown'
            else:
                file_type = 'unknown'
    except Exception:
        file_type = 'unknown'

    return {prefix: {'type': file_type, 'path': file_path}}

