def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Determine the original file by stripping the language suffix
    # before the file extension (assumes separator '-').
    if not isinstance(file_path, str) or not isinstance(lang, str):
        raise TypeError("file_path and lang must be strings")

    # Find the last dot and hyphen before the dot
    dot_index = file_path.rfind('.')
    hyphen_index = file_path.rfind('-', dot_index)

    if hyphen_index != -1:
        original = file_path[:hyphen_index] + file_path[dot_index:]
    else:
        # No language suffix; assume the given file is the original
        original = file_path

    # Build the mapping dictionary
    mapping = {"original": original, lang: file_path}

    # Store the mapping in an attribute `renditions` on the instance.
    # Use the base name (without extension) of the original file as the key.
    base_key = original.rsplit('.', 1)[0]
    if not hasattr(self, "renditions"):
        self.renditions = {}
    self.renditions[base_key] = mapping

    return mapping

