def _extract_number_and_supplment_from_issue_element(issue):
    """Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Get text from the element safely
    content = (issue.text or "").strip()
    if not content:
        return None, None

    lower = content.lower()

    # Helper to find all number-like substrings (digits or digits-hyphen-digits)
    def find_numbers(text):
        nums = []
        i = 0
        L = len(text)
        while i < L:
            if text[i].isdigit():
                start = i
                while i < L and (text[i].isdigit() or text[i] == '-'):
                    i += 1
                nums.append(text[start:i])
            else:
                i += 1
        return nums

    # Find main issue number (first numeric pattern)
    numbers = find_numbers(lower)
    main_num = None
    if numbers:
        main_num = numbers[0]  # take the first numeric pattern found

    # Detect supplemental keyword and its number
    sup_keywords = ["suppl", "spe", "supp", "supl", "s"]
    suppl_num = None
    for kw in sup_keywords:
        idx = lower.find(kw)
        if idx != -1:
            # Look for a number after the keyword
            rest = content[idx + len(kw):]
            rest_nums = find_numbers(rest.lower())
            if rest_nums:
                suppl_num = rest_nums[0]
            else:
                # No explicit number after keyword => assume 1
                suppl_num = "1"
            break

    def to_int_or_str(v):
        if v is None:
            return None
        try:
            return int(v)
        except ValueError:
            return v

    return to_int_or_str(main_num), to_int_or_str(suppl_num)

