def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # Determine the UTC offset for the original datetime.
    try:
        offset_dt = self.utcoffset(dt)
    except Exception:
        offset_dt = None

    # Use a small window to detect if the datetime lies at a DST transition.
    delta = datetime.timedelta(seconds=30)
    before = dt - delta
    after = dt + delta

    try:
        offset_before = self.utcoffset(before)
    except Exception:
        offset_before = None

    try:
        offset_after = self.utcoffset(after)
    except Exception:
        offset_after = None

    # Default fold is 0 (first occurrence).
    fold = 0
    if (
        offset_before is not None
        and offset_after is not None
        and offset_before != offset_after
    ):
        # If the offset for dt matches the offset just before the transition,
        # it is the first instance; otherwise it is the second.
        if offset_dt == offset_before:
            fold = 0
        elif offset_dt == offset_after:
            fold = 1

    # Apply the determined fold if the datetime object supports it.
    if hasattr(dt, "fold"):
        try:
            return dt.replace(fold=fold)
        except Exception:
            # Some datetime implementations may not allow setting fold via replace.
            return dt
    return dt

