def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Sequence
        Version components in the order: major, minor, patch, prerelease (optional), build (optional).
        Each component may be an integer or a string. Non‑numeric components are treated as
        prerelease or build metadata respectively.

    style : str or callable
        If a string, it must be one of the predefined styles:
        'semver'    : <major>.<minor>.<patch>[-pre][+build]
        'pep440'    : <major>.<minor>.<patch>[aN][+build]
        'short'     : <major>.<minor>.<patch>
        'full'      : same as 'semver'
        'raw'       : concatenate all pieces with hyphens.
        If callable, it will be invoked as ``style(pieces)`` and its return value used.

    Returns
    -------
    str
        The rendered version string.
    """
    # If style is a callable, delegate to it
    if callable(style):
        return style(pieces)

    # Ensure pieces is a list for indexing
    pe = list(pieces)

    # Extract main components, defaulting to 0 for missing parts
    try:
        major = str(int(pe[0]))
    except Exception:
        major = "0"
    try:
        minor = str(int(pe[1]))
    except Exception:
        minor = "0"
    try:
        patch = str(int(pe[2]))
    except Exception:
        patch = "0"

    # Remaining components: prerelease, build
    prerelease = None
    build = None
    if len(pe) > 3:
        # treat the next non‑numeric entry as prerelease
        pr = pe[3]
        if isinstance(pr, int) or (isinstance(pr, str) and pr.isdigit()):
            # numeric, treat as prerelease if provided as separate element
            prerelease = str(pr)
        else:
            prerelease = str(pr)
    if len(pe) > 4:
        build = str(pe[4])

    # Build the base string
    base = f"{major}.{minor}.{patch}"

    if style in ("semver", "full"):
        result = base
        if prerelease:
            result += f"-{prerelease}"
        if build:
            result += f"+{build}"
        return result

    elif style == "pep440":
        # PEP 440 uses 'a', 'b', 'rc' before the number or just a number for alpha
        # For simplicity, we attach 'a' if prerelease is alpha-like,
        # otherwise leave as is.
        result = base
        if prerelease:
            if prerelease.lower().startswith(("alpha", "a", "beta", "b", "rc", "c")):
                # Extract the numeric part if present
                import re
                m = re.match(r"(?i)(alpha|beta|rc|a|b|c)?(\d*)", prerelease)
                if m:
                    prefix = m.group(1)
                    num = m.group(2)
                    if prefix is None or prefix in ("alpha", "a"):
                        result += f"a{num}"
                    elif prefix in ("beta", "b"):
                        result += f"b{num}"
                    elif prefix in ("rc", "c"):
                        result += f"rc{num}"
                    else:
                        result += f"{prerelease}"
                else:
                    result += f"{prerelease}"
            else:
                result += f"{prerelease}"
        if build:
            result += f"+{build}"
        return result

    elif style == "short":
        return base

    elif style == "raw":
        # Concatenate all parts with hyphens
        return "-".join(str(p) for p in pe)

    else:
        raise ValueError(f"Unknown style '{style}'")

