def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        cmd = [commands]
    cmd.extend(args)

    if verbose:
        # Pretty print the command
        try:
            import shlex
            cmd_str = " ".join(shlex.quote(str(c)) for c in cmd)
        except ImportError:
            cmd_str = " ".join(str(c) for c in cmd)
        print(f"Running command: {cmd_str}")

    # Determine stdout and stderr handling
    stdout = subprocess.PIPE if not verbose else None
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=stdout,
            stderr=stderr,
            check=True,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        # If verbose, print captured output before raising
        if verbose and exc.stdout:
            print(exc.stdout)
        raise RuntimeError(
            f"Command '{' '.join(map(str, cmd))}' returned non-zero exit status {exc.returncode}."
        ) from exc

    # If verbose, print stdout
    if verbose and result.stdout:
        print(result.stdout)

    return result

