def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import yaml

    # Ensure attributes exist
    if not hasattr(self, "missing_inventories"):
        self.missing_inventories = []
    if not hasattr(self, "digest_differences"):
        self.digest_differences = {}

    root_inv_path = os.path.join(self.root_dir, "inventory.yaml")
    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inv = yaml.safe_load(f) or {}
    except Exception:
        root_inv = {}

    # Map of file_path -> digest from root inventory
    root_digests = {fp: rec.get("digest") for fp, rec in root_inv.items() if isinstance(rec, dict)}

    # Iterate through each version directory
    for ver_dir in version_dirs:
        inv_path = os.path.join(self.root_dir, ver_dir, "inventory.yaml")
        if not os.path.exists(inv_path):
            # Record missing inventory
            self.missing_inventories.append(ver_dir)
            continue
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                ver_inv = yaml.safe_load(f) or {}
        except Exception:
            ver_inv = {}

        # Compare digests with the root inventory
        for fp, rec in ver_inv.items():
            if not isinstance(rec, dict):
                continue
            ver_digest = rec.get("digest")
            root_digest = root_digests.get(fp)
            # If root has a digest and they differ, record the discrepancy
            if root_digest is not None and ver_digest != root_digest:
                self.digest_differences.setdefault(fp, {}).update(
                    {ver_dir: ver_digest}
                )
    # Return True if all inventories are present and no digest discrepancies found
    return len(self.missing_inventories) == 0 and len(self.digest_differences) == 0

