def deep_merge_nodes(nodes):
    '''
    Merge duplicate keys in a list of key/value node pairs. If the
    values for a duplicate key are both MappingNodes their contents are
    merged recursively; otherwise the last value wins.
    '''
    # Helper to check for MappingNode like objects
    def is_mapping(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    # Merge two mapping nodes in place: node_a receives changes from node_b
    def merge_mapping_nodes(node_a, node_b):
        # Build a dict for node_a's current key->(key_node,val_node)
        a_dict = {k.value: (k, v) for k, v in node_a.value}
        for k_b, v_b in node_b.value:
            key = k_b.value
            if key in a_dict:
                k_a, v_a = a_dict[key]
                if is_mapping(v_a) and is_mapping(v_b):
                    merge_mapping_nodes(v_a, v_b)
                else:
                    # replace existing value with the new one
                    for idx, (k_cur, _) in enumerate(node_a.value):
                        if k_cur.value == key:
                            node_a.value[idx] = (k_b, v_b)
                            break
                    a_dict[key] = (k_b, v_b)
            else:
                node_a.value.append((k_b, v_b))
                a_dict[key] = (k_b, v_b)

    result_map = {}
    order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key in result_map:
            # duplicate key
            _, existing_val = result_map[key]
            if is_mapping(existing_val) and is_mapping(val_node):
                merge_mapping_nodes(existing_val, val_node)
            else:
                # last value wins
                result_map[key] = (key_node, val_node)
        else:
            result_map[key] = (key_node, val_node)
            order.append(key)

    # Build result list preserving insertion order
    merged = [result_map[k] for k in order]
    return merged

