def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by
    introspecting borgmatic's command-line argument parsers.
    """
    import subprocess
    import textwrap

    try:
        help_output = subprocess.check_output(
            ["borgmatic", "--help"],
            stderr=subprocess.DEVNULL,
            text=True,
        )
    except Exception:
        # If unable to run borgmatic or capture output, return an empty script.
        return ""

    # Extract options that start with '-' or '--'.
    options = set()
    for line in help_output.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith("-"):
            # Split options by commas or spaces; keep those that start with '-'
            parts = [p.strip() for p in stripped.replace(",", " ").split()]
            for part in parts:
                if part.startswith("-"):
                    # Keep only the option form, strip any trailing space or argument
                    opt = part.split()[0]
                    options.add(opt)

    if not options:
        return ""

    opts_str = " ".join(sorted(options))

    script = textwrap.dedent(
        f"""
        _borgmatic_completion() {{
            local cur prev words cword
            _init_completion -s || return
            COMPREPLY=($(compgen -W "{opts_str}" -- "$cur"))
        }}
        complete -F _borgmatic_completion borgmatic
        """
    ).strip()

    return script

