def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two digits for base conversion")

    negative = number < 0
    n = -number if negative else number

    # Special case for zero
    if n == 0:
        result = alphabet[0]
    else:
        digits: List[str] = []
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    if padding is not None:
        if padding < 0:
            raise ValueError("Padding must be non-negative or None")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    if negative:
        result = '-' + result

    return result

