def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, 
    sort the list for only ignored files, and return those files as a 
    single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            stderr=subprocess.DEVNULL,
            text=True
        )
    except subprocess.CalledProcessError:
        return ""
    files = sorted(line.strip() for line in output.splitlines() if line.strip())
    return ",".join(files)

