def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine if 'matcher' is a regex match object or a plain string
    if hasattr(matcher, "groupdict") or hasattr(matcher, "group"):
        # Prefer explicit named groups if available
        if hasattr(matcher, "groupdict"):
            group_dict = matcher.groupdict()
            var_name = group_dict.get("name") or group_dict.get("var") or group_dict.get("0")
        else:
            # fall back to positional groups
            var_name = matcher.group(1)

        default_val = None
        # Try to fetch default from a named group 'default' or positional group 2
        if hasattr(matcher, "groupdict"):
            default_val = group_dict.get("default")
        else:
            try:
                default_val = matcher.group(2)
            except IndexError:
                default_val = None

        # Resolve the value from environment
        value = os.getenv(var_name, default_val)

        if value is None:
            raise KeyError(f"Environment variable '{var_name}' not found and no default value provided")

        return value

    else:
        # Assume matcher is a plain variable name string
        var_name = str(matcher)
        value = os.getenv(var_name)
        if value is None:
            raise KeyError(f"Environment variable '{var_name}' not found and no default value provided")
        return value

