def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json, os, re
    config_map = {}
    errors = []
    env_pattern = re.compile(r'\$\{([^}]+)\}')
    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                config = json.load(f)
            if overrides:
                config.update(overrides)
            if resolve_env:
                def resolve(val):
                    if isinstance(val, str):
                        for m in env_pattern.findall(val):
                            val = val.replace(f"${{{m}}}", os.getenv(m, ''))
                        return val
                    return val
                def resolve_dict(d):
                    for k, v in d.items():
                        if isinstance(v, dict):
                            resolve_dict(v)
                        else:
                            d[k] = resolve(v)
                resolve_dict(config)
            config_map[fname] = config
        except Exception as exc:
            record = logging.LogRecord(
                name=__name__,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            errors.append(record)
    return config_map, errors

