def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If `other` is `None`, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to `recompute`).
    After changing (filling) the histogram one must explicitly recompute
    the scale if it was computed before.

    If a float `other` is provided, rescale self to `other`.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper: computing the scale from the raw contents
    def _compute_scale_from_contents():
        # If histogram stores counts or heights in self._contents (or similar),
        # we try to sum them. This is a generic fallback; derived classes
        # should override or provide the attribute accordingly.
        if hasattr(self, "_counts"):
            return sum(self._counts)
        if hasattr(self, "_contents"):
            return sum(self._contents)
        if hasattr(self, "_values"):
            return sum(self._values)
        raise AttributeError("Histogram object has no known array of values to compute scale from")

    # Get or compute current scale
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or recompute:
        current_scale = _compute_scale_from_contents()
        self._scale = current_scale

    # If only querying, return the current scale
    if other is None:
        return current_scale

    # Rescaling requested
    # Ensure the current scale is non-zero
    if current_scale == 0:
        raise LenaValueError("Cannot rescale a histogram with a scale of zero")

    # Compute the factor by which to scale the underlying contents
    try:
        factor = float(other) / current_scale
    except Exception as err:
        raise TypeError("The 'other' argument must be a numeric type") from err

    # Apply scaling to the stored contents
    # Prefer in-place multiplication for numpy arrays; fall back to list comprehension
    if hasattr(self, "_counts"):
        try:
            self._counts *= factor
        except Exception:
            self._counts = [c * factor for c in self._counts]
    elif hasattr(self, "_contents"):
        try:
            self._contents *= factor
        except Exception:
            self._contents = [c * factor for c in self._contents]
    elif hasattr(self, "_values"):
        try:
            self._values *= factor
        except Exception:
            self._values = [c * factor for c in self._values]
    else:
        raise AttributeError("Histogram object has no known array of values to rescale")

    # Store the new scale
    self._scale = float(other)
    return self._scale

