def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph (as a list of dictionaries in this generic
    implementation).
    """
    # helpers to get axis information
    def get_nb_bins():
        if hasattr(hist, "GetNbinsX"):
            return hist.GetNbinsX()
        if hasattr(hist, "nbins"):
            return hist.nbins
        if hasattr(hist, "__len__"):
            # assume number of contents equals number of bins
            return len(hist)
        raise AttributeError("Histogram object does not provide bin count")

    def get_low_edge(i):
        if hasattr(hist, "GetXaxis") and hasattr(hist.GetXaxis(), "GetBinLowEdge"):
            return hist.GetXaxis().GetBinLowEdge(i)
        if hasattr(hist, "xlow"):
            return hist.xlow(i)
        if hasattr(hist, "edges"):
            # edges length should be nbins+1
            return hist.edges[i]
        raise AttributeError("Cannot get low edge of bin %d" % i)

    def get_width(i):
        if hasattr(hist, "GetXaxis") and hasattr(hist.GetXaxis(), "GetBinWidth"):
            return hist.GetXaxis().GetBinWidth(i)
        if hasattr(hist, "xwidth"):
            return hist.xwidth(i)
        if hasattr(hist, "edges"):
            return hist.edges[i + 1] - hist.edges[i]
        # fallback to 1 if nothing else
        return 1.0

    def get_content(i):
        if hasattr(hist, "GetBinContent"):
            return hist.GetBinContent(i)
        if hasattr(hist, "__getitem__"):
            return hist[i - 1]
        if hasattr(hist, "contents"):
            return hist.contents[i - 1]
        raise AttributeError("Cannot get content of bin %d" % i)

    nbins = get_nb_bins()
    result = []

    # if scale is provided and True, attempt to copy it
    graph_scale = None
    if scale is True:
        if hasattr(hist, "scale"):
            graph_scale = hist.scale
        elif hasattr(hist, "GetScale"):
            graph_scale = hist.GetScale()
        # otherwise remain None

    for i in range(1, nbins + 1):
        low = get_low_edge(i)
        width = get_width(i)

        if get_coordinate == "left":
            x = low
        elif get_coordinate == "right":
            x = low + width
        else:  # middle
            x = low + width / 2

        content = get_content(i)

        if make_value is not None:
            val = make_value(content)
        else:
            val = content

        # Build point dictionary
        point = {}
        point[field_names[0]] = x

        # Determine values for remaining fields
        if isinstance(val, (tuple, list)):
            if len(val) + 1 != len(field_names):
                raise ValueError(
                    "Number of values from make_value does not match field_names"
                )
            for name, v in zip(field_names[1:], val):
                point[name] = v
        else:
            # single value for the second field
            if len(field_names) > 1:
                point[field_names[1]] = val
                # fill any remaining fields with None
                for name in field_names[2:]:
                    point[name] = None
            else:
                # only x field
