def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        return type
    # Determine the most derived metaclass from the base classes
    if explicit_mc is None:
        # Start with the metaclass of the first base
        mcls = type(bases[0])
        for b in bases[1:]:
            mb = type(b)
            if mb is mcls:
                continue
            if issubclass(mb, mcls):
                mcls = mb
            elif not issubclass(mcls, mb):
                raise TypeError(f"metaclass conflict: {mcls} conflicts with {mb}")
        return mcls
    # explicit metaclass is given; ensure it is a type
    if not isinstance(explicit_mc, type):
        raise TypeError(f"__metaclass__ must be a type object, not {explicit_mc!r}")
    # All base metaclasses must be subclasses of the explicit one
    for b in bases:
        mb = type(b)
        if not issubclass(mb, explicit_mc):
            raise TypeError(f"metaclass conflict: {explicit_mc} is not a superclass of {mb}")
    return explicit_mc

