def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    # Ensure the datetime is represented in UTC and formatted as
    # an ISO-8601 string without microseconds, ending with 'Z'.
    if dt.tzinfo is None:
        # Assume naive datetimes are already in UTC
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    # Convert to UTC by subtracting the time zone offset
    offset = dt.utcoffset()
    if offset is None:
        # If utcoffset cannot be computed we fall back to naive formatting
        utc_dt = dt
    else:
        utc_dt = dt - offset
    return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')

