def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    # Find all code blocks (inline and fenced)
    code_pattern = r'(```[\s\S]+?```|`[^`]*`)'
    codes = []
    placeholders = {}
    result = text
    # Replace code blocks with placeholders
    for i, m in enumerate(re.finditer(code_pattern, text)):
        code = m.group(0)
        placeholder = f"___CODE_BLOCK_{i}___"
        placeholders[placeholder] = code
        result = result.replace(code, placeholder)
    # Now find tags in the non-code part
    tag_pattern = r'#(\w+)'  # tags are words preceded by '#'
    tags = set()
    def replace_tag(match):
        tag = match.group(1)
        tags.add(tag)
        if replacer:
            return replacer(tag)
        else:
            return match.group(0)
    result = re.sub(tag_pattern, replace_tag, result)
    # Put back original code blocks
    for placeholder, code in placeholders.items():
        result = result.replace(placeholder, code)
    return tags, result

