def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    def topleft(part):
        return f' {part}'
    def add_anchor_attrs(tag):
        # Ensure the tag starts with <a
        if not tag.lower().startswith('<a'):
            return tag
        # Skip if tag already has target or rel attributes
        if 'target=' in tag or 'rel=' in tag:
            return tag
        # Find the position of '>'
        endpos = tag.find('>')
        if endpos == -1:
            return tag
        # Insert attributes just before the '>'
        return f'{tag[:endpos]} target="_blank" rel="noopener noreferrer"{tag[endpos:]}'
    def linkify(segment):
        result = []
        i = 0
        while i < len(segment):
            # Find next http:// or https://
            pos_http = segment.find('http://', i)
            pos_https = segment.find('https://', i)
            if pos_http == -1:
                pos_http = len(segment) + 1
            if pos_https == -1:
                pos_https = len(segment) + 1
            pos = min(pos_http, pos_https)
            if pos > len(segment) - 1:
                result.append(segment[i:])
                break
            # Append text before the URL
            result.append(segment[i:pos])
            # Find end of URL (stop at whitespace or common punctuation)
            end = pos
            while end < len(segment) and segment[end] not in ' \t\n\r,;.!?:)]+/\\\'"<>':
                end += 1
            url = segment[pos:end]
            href = f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
            result.append(href)
            i = end
        return ''.join(result)
    # Split the text into tags and non-tag parts
    parts = []
    idx = 0
    while idx < len(text):
        lt = text.find('<', idx)
        if lt == -1:
            parts.append((False, text[idx:]))
            break
        gt = text.find('>', lt)
        if gt == -1:
            parts.append((False, text[idx:]))
            break
        # Text before the tag
        if lt > idx:
            parts.append((False, text[idx:lt]))
        # The tag itself
        parts.append((True, text[lt:gt+1]))
        idx = gt + 1
    # Process each part
    output = []
    for is_tag, part in parts:
        if is_tag:
            part = add_anchor_attrs(part)
            output.append(part)
        else:
            output.append(linkify(part))
    return ''.join(output)

