    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    doc = document.strip()
    # Try JSON first
    if doc.startswith('{') or doc.startswith('['):
        try:
            data = json.loads(doc)
        except Exception:
            data = None
        if isinstance(data, dict):
            # Normalize rel field in links to list
            if 'links' in data and isinstance(data['links'], list):
                for link in data['links']:
                    rel = link.get('rel')
                    if isinstance(rel, str):
                        link['rel'] = [r for r in rel.split() if r]
                    elif not isinstance(rel, list):
                        link['rel'] = []
            return data
    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        return {}
    # Extract namespace if present
    ns = {}
    if root.tag.startswith('{'):
        uri, _ = root.tag[1:].split('}')
        ns = {'ns': uri}
        find = lambda path: root.find('.//ns:' + path, ns)
        findall = lambda path: root.findall('.//ns:' + path, ns)
    else:
        find = lambda path: root.find('.//' + path)
        findall = lambda path: root.findall('.//' + path)

    subject_el = find('Subject')
    subject = subject_el.text.strip() if subject_el is not None and subject_el.text else None

    alias_els = findall('Alias')
    aliases = [el.text.strip() for el in alias_els if el.text and el.text.strip()]

    links = []
    for link_el in findall('Link'):
        href = link_el.get('href')
        ltype = link_el.get('type')
        rel_attr = link_el.get('rel')
        rel_list = [r for r in rel_attr.split() if r] if rel_attr else []
        # also collect nested <Rel> elements
        for rel_child in link_el.findall('.//Rel'):
            if rel_child.text:
                for r in rel_child.text.split():
                    if r not in rel_list:
                        rel_list.append(r)
        links.append({'href': href, 'type': ltype, 'rel': rel_list})

    result = {}
    if subject is not None:
        result['subject'] = subject
    if aliases:
        result['aliases'] = aliases
    if links:
        result['links'] = links

    return result

