def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve mapping of argument names to allowed choices.
    # The class is expected to provide a `_choices` attribute either as a
    # mapping {arg_name: [allowed_values]} or similar.  If no mapping is
    # present we cannot validate any choices, so silently return.
    choices_map = getattr(self, "_choices", None)
    if not choices_map:
        return

    for arg_name, allowed_values in choices_map.items():
        # Skip validation if the argument isn't present in the supplied args.
        if arg_name not in args:
            continue

        value = args[arg_name]

        # Normalise the allowed values to a set for fast lookup.
        if isinstance(allowed_values, (list, tuple, set)):
            allowed_set = set(allowed_values)
        else:
            # If allowed_values is not an iterable we cannot validate it.
            # Move on to the next argument.
            continue

        # If the value itself is an iterable (but not a string/bytes),
        # validate each element separately.  This allows users to pass
        # comma‑separated lists for multi‑value choice arguments.
        if isinstance(value, (list, tuple, set)):
            for item in value:
                if item not in allowed_set:
                    raise ValueError(
                        f"Invalid choice for '{arg_name}': '{item}'. "
                        f"Allowed values: {sorted(allowed_set)}"
                    )
        else:
            if value not in allowed_set:
                raise ValueError(
                    f"Invalid choice for '{arg_name}': '{value}'. "
                    f"Allowed values: {sorted(allowed_set)}"
                )

