def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        :type args: dict
        :raises ValueError: If an argument value is not among its allowed choices.
        """
        # Determine where allowed choices are stored. This method is intentionally
        # generic and will work with common patterns such as:
        # - self.choices: a dict mapping argument names to an iterable of allowed values
        # - self._choices: similar, sometimes used internally
        # The method will ignore arguments that are not defined as choice arguments.
        choices_map = getattr(self, "choices", None)
        if choices_map is None:
            # fallback to internal attribute names
            choices_map = getattr(self, "_choices", {})
            if choices_map is None:
                choices_map = {}

        for arg_name, arg_value in args.items():
            if arg_name not in choices_map:
                continue  # not a choice argument

            allowed = choices_map[arg_name]
            # Support both singular values and iterables (e.g., list/tuple of choices).
            if isinstance(arg_value, (list, tuple, set)):
                invalid = [v for v in arg_value if v not in allowed]
                if invalid:
                    allowed_str = ", ".join(map(str, allowed))
                    invalid_str = ", ".join(map(str, invalid))
                    raise ValueError(
                        f"Invalid value(s) for argument '{arg_name}': {invalid_str}. "
                        f"Allowed choices: {allowed_str}."
                    )
            else:
                if arg_value not in allowed:
                    allowed_str = ", ".join(map(str, allowed))
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {arg_value}. "
                        f"Allowed choices: {allowed_str}."
                    )
        # No return value needed; method raises if validation fails
        return

