def validate_min_max_args(self, args):
    """
    Validate that numeric values provided in *args* are within the specified
    minimum and maximum ranges.

    ``args`` can be:
        * a single numeric value
        * a sequence of numeric values
        * a mapping or sequence of mappings each containing the keys
          ``value``, ``min`` and ``max``
        * a mapping where the keys are names and the values are numeric.
          In this case the object must have attributes ``min`` and ``max``
          that are applied to every value.

    If all values fall within their respective ranges the method returns
    ``True``; otherwise a ``ValueError`` is raised and ``False`` is returned.

    """
    def _check_value(value, minimum, maximum, name="value"):
        if not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a numeric type, got {type(value).__name__}")
        if value < minimum or value > maximum:
            raise ValueError(f"{name} {value} not in [{minimum}, {maximum}]")

    # 1. Handle a single numeric value
    if isinstance(args, (int, float)):
        if not hasattr(self, "min") or not hasattr(self, "max"):
            raise AttributeError("The object must have 'min' and 'max' attributes")
        _check_value(args, self.min, self.max, name="args")
        return True

    # 2. Handle mappings where values are numeric and min/max are defined on the instance
    if isinstance(args, dict):
        if not hasattr(self, "min") or not hasattr(self, "max"):
            # Attempt to validate each mapping individually
            for key, val in args.items():
                _check_value(val, self.min, self.max, name=f"{key}")
            return True
        for key, val in args.items():
            _check_value(val, self.min, self.max, name=f"{key}")
        return True

    # 3. Handle iterable sequences (list, tuple, set, etc.) that may contain numbers or dicts
    iterable = None
    try:
        # Avoid treating strings as iterable of values
        if not isinstance(args, (str, bytes)):
            iterable = iter(args)
    except TypeError:
        pass

    if iterable is None:
        raise TypeError("First argument must be a numeric value, a mapping, or an iterable of values")

    for idx, item in enumerate(iterable):
        if isinstance(item, (int, float)):
            # Without explicit min/max, fall back to object's attributes
            if not hasattr(self, "min") or not hasattr(self, "max"):
                raise AttributeError("The object must have 'min' and 'max' attributes for numeric items")
            _check_value(item, self.min, self.max, name=f"args[{idx}]")
        elif isinstance(item, dict):
            if not all(k in item for k in ("value", "min", "max")):
                raise ValueError(f"Dictionary at index {idx} must contain 'value', 'min', and 'max' keys")
            _check_value(item["value"], item["min"], item["max"], name=f"args[{idx}]['value']")
        else:
            raise TypeError(f"Unsupported item type at index {idx}: {type(item).__name__}")

    return True

