    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to recursively flatten a dictionary
    def _flatten(d, parent_key='', sep='.', result=None):
        if result is None:
            result = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key, sep, result)
            elif isinstance(v, list):
                # Convert lists to comma-separated strings
                result[new_key] = ','.join(map(str, v))
            else:
                result[new_key] = v
        return result

    # Determine possible spec filenames
    spec_filenames = ['plugin.json', 'plugin.yml', 'plugin.yaml', 'plugin_spec.json', 'plugin_spec.yaml']
    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.exists(candidate):
            spec_path = candidate
            break

    if not spec_path:
        # No spec file found
        return {}

    # Load spec content
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception:
        return {}

    # Try JSON first
    try:
        spec_dict = json.loads(content)
    except json.JSONDecodeError:
        # If JSON failed, try YAML if available
        spec_dict = None
        try:
            import yaml  # type: ignore
            spec_dict = yaml.safe_load(content)
        except Exception:
            pass

    if not isinstance(spec_dict, dict):
        return {}

    return _flatten(spec_dict)

