        return {}

    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            import json
            spec_data = json.load(f)
    except Exception:
        # If the file cannot be decoded as JSON, return empty dict
        return {}

    # Flatten the loaded dictionary
    return _flatten(spec_data)

